The exact same Module 18 pattern, now with hexagonal
architecture's formal vocabulary made explicit:

// PORT: a technology-agnostic interface that the domain defines
// (the Repository interface Module 18 used is exactly this)
interface UserRepository {
  findById(id: string): Promise<User | null>;
  save(user: User): Promise<void>;
}

// DOMAIN (the innermost layer - depends on nothing external)
class UserService {
  constructor(private userRepo: UserRepository) {}
  // depends only on the PORT (the interface), not any adapter

  async deactivateUser(userId: string): Promise<void> {
    const user = await this.userRepo.findById(userId);
    if (!user) throw new NotFoundError('User not found');
    user.deactivate(); // pure domain logic - no database, no HTTP
    await this.userRepo.save(user);
  }
}

// ADAPTER (a specific technology plugging into the PORT)
class PostgresUserRepository implements UserRepository {
  async findById(id: string): Promise<User | null> {
    const row = await db.query('SELECT * FROM users WHERE id = $1', [id]);
    return row ? mapRowToUser(row) : null;
  }
  async save(user: User): Promise<void> {
    await db.query('UPDATE users SET ... WHERE id = $1', [user.id]);
  }
}
// Module 18's pattern WAS hexagonal architecture -
// this lesson just names and formalizes it

