// PORT: technology-agnostic interface the domain depends on
interface Order {
  id: string;
  status: 'pending' | 'shipped' | 'cancelled';
  userId: string;
}

interface OrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

// DOMAIN: depends only on the port, not any adapter
class OrderService {
  constructor(private orderRepo: OrderRepository) {}

  async cancelOrder(orderId: string): Promise<void> {
    const order = await this.orderRepo.findById(orderId);
    if (!order) throw new Error('Order not found');
    if (order.status === 'shipped') throw new Error('Cannot cancel shipped order');
    await this.orderRepo.save({ ...order, status: 'cancelled' });
  }
}

// PRODUCTION ADAPTER: PostgreSQL
class PostgresOrderRepository implements OrderRepository {
  constructor(private db: Pool) {}

  async findById(id: string): Promise<Order | null> {
    const result = await this.db.query('SELECT * FROM orders WHERE id = $1', [id]);
    return result.rows[0] ? mapRowToOrder(result.rows[0]) : null;
  }

  async save(order: Order): Promise<void> {
    await this.db.query('UPDATE orders SET status = $2 WHERE id = $1', [order.id, order.status]);
  }
}

// TEST ADAPTER: in-memory
class InMemoryOrderRepository implements OrderRepository {
  private orders = new Map<string, Order>();

  async findById(id: string): Promise<Order | null> {
    return this.orders.get(id) ?? null;
  }

  async save(order: Order): Promise<void> {
    this.orders.set(order.id, order);
  }
}

