An e-commerce domain decomposed into bounded contexts,
directly answering 'where should the service boundaries go?':

// BOUNDED CONTEXT 1: Order Management
// Ubiquitous language within this context:
interface Order {
  orderId: string;
  lineItems: LineItem[];
  shippingAddress: Address;
  status: OrderStatus; // 'placed' | 'confirmed' | 'shipped' | 'delivered'
}
// 'Order' here means a purchase event with line items

// BOUNDED CONTEXT 2: Inventory
// Same word 'product', completely different model:
interface StockItem {
  productId: string;
  sku: string;
  warehouseLocation: string;
  quantityAvailable: number;
  reorderThreshold: number;
}
// 'Product' here means a physical item with a warehouse location

// BOUNDED CONTEXT 3: Customer (Billing view)
interface CustomerAccount {
  accountId: string;
  paymentMethods: PaymentMethod[];
  outstandingBalance: Money;
  subscriptionStatus: SubscriptionStatus;
}
// 'Customer' here means a billing relationship

// CONTEXT MAPPING: Order Management needs to know inventory
// but must communicate across the context boundary
interface InventoryCheckRequest {
  productId: string;   // shared identifier that crosses the boundary
  quantity: number;
}

