// When an order is placed in the Order Management context,
// it needs to reserve inventory in the Inventory context.
// The WRONG approach: Order Management directly imports
// Inventory's internal StockItem model - crosses the context boundary

// THE CORRECT APPROACH: communicate via a context-mapping event
// that contains only the shared data, not the internal models

// In the Order Management context:
async function placeOrder(orderData: CreateOrderInput): Promise<Order> {
  const order = Order.create(orderData);
  await orderRepository.save(order);

  // Publish an event that crosses the context boundary
  // using ONLY shared identifiers, not internal models
  await eventBus.publish('order-management.order-placed', {
    orderId: order.orderId,
    lineItems: order.lineItems.map(item => ({
      productId: item.productId, // shared identifier
      quantity: item.quantity
    }))
    // Note: NO shippingAddress, status, or other Order Management
    // internal fields that the Inventory context doesn't need
  });

  return order;
}

// In the Inventory context (separate service or module):
eventBus.subscribe('order-management.order-placed', async (event) => {
  for (const item of event.lineItems) {
    // Inventory context uses its OWN internal model, not Order's
    const stockItem = await stockRepository.findBySku(item.productId);
    stockItem.reserveQuantity(item.quantity);
    await stockRepository.save(stockItem);
  }
});

