// BOUNDED CONTEXTS:

// 1. Scheduling Context
// 'Patient' = a bookable entity with a preferred doctor and
//   time-slot preferences
interface SchedulingPatient {
  patientId: string;
  preferredProviderId: string;
  appointmentHistory: AppointmentSlot[];
  timezone: string;
}

// 2. Clinical Context
// 'Patient' = a medical subject with health history
interface ClinicalPatient {
  patientId: string;
  dateOfBirth: Date;
  allergies: Allergy[];
  diagnoses: Diagnosis[];
  currentMedications: Medication[];
}

// 3. Billing Context
// 'Patient' = a payer with insurance and financial relationships
interface BillingPatient {
  patientId: string;
  primaryInsurance: InsurancePlan;
  secondaryInsurance?: InsurancePlan;
  outstandingBalance: Money;
  paymentMethod: PaymentMethod;
}

// CONTEXT MAPPING EVENT: Scheduling -> Billing
// Contains ONLY what Billing needs, using shared identifiers,
// not Scheduling's full internal AppointmentSlot model
interface AppointmentScheduledEvent {
  eventType: 'scheduling.appointment-scheduled';
  appointmentId: string;        // shared identifier
  patientId: string;            // shared identifier
  providerId: string;           // shared identifier
  appointmentDateTime: string;  // shared data Billing needs for claim timing
  serviceType: string;          // e.g. 'consultation', 'follow-up'
  // NOT included: reminder settings, room assignment, slot duration
  // (Scheduling internal data Billing doesn't need)
}

// Billing subscribes and builds ITS OWN internal model:
billingEventBus.subscribe('scheduling.appointment-scheduled',
  async (event: AppointmentScheduledEvent) => {
    const expectedClaim = ExpectedClaim.create({
      appointmentId: event.appointmentId,
      patientId: event.patientId,
      // Billing fetches its own patient record using the shared patientId
      billingPatient: await billingPatientRepo.findById(event.patientId),
      serviceType: event.serviceType,
      scheduledDate: new Date(event.appointmentDateTime)
    });
    await expectedClaimRepo.save(expectedClaim);
  }
);

