A minimal but complete CQRS implementation directly extending
Module 18's Controller/Service/Repository pattern:

// COMMAND SIDE: optimized for writes and business rule enforcement
class OrderCommandService {
  constructor(private orderRepo: OrderRepository) {}

  async placeOrder(command: PlaceOrderCommand): Promise<string> {
    // Business rule validation happens HERE in the command model
    const inventory = await this.checkInventory(command.items);
    if (!inventory.allAvailable) throw new InsufficientInventoryError();

    const order = Order.create(command);
    await this.orderRepo.save(order); // persists the canonical state
    await this.eventBus.publish('order-placed', { orderId: order.id });
    return order.id;
  }
}

// QUERY SIDE: optimized for reads, denormalized for specific UIs
// (this is exactly Module 35's OLAP read model)
interface OrderSummaryView {
  orderId: string;
  customerName: string;       // denormalized from Customer context
  itemDescriptions: string[]; // denormalized from Product context
  totalFormatted: string;     // pre-formatted for display
  statusLabel: string;        // UI-friendly status string
}

class OrderQueryService {
  constructor(private readDb: ReadonlyDatabase) {}

  async getOrdersForUser(userId: string): Promise<OrderSummaryView[]> {
    // Reads from a denormalized view pre-joined with customer/product data
    return this.readDb.query(
      'SELECT * FROM order_summary_view WHERE user_id = $1',
      [userId]
    );
  }
}

