// EVENT STORE: append-only log of domain events
// (This is what Module 28's domain events were pointing toward)
interface OrderEvent {
  eventId: string;
  orderId: string;
  eventType: 'OrderPlaced' | 'ItemAdded' | 'OrderCancelled' | 'OrderShipped';
  eventData: Record<string, unknown>;
  occurredAt: Date;
}

// RECONSTITUTE current state from events (the replay pattern)
function reconstitute(events: OrderEvent[]): Order {
  let order: Partial<Order> = {};

  for (const event of events) {
    switch (event.eventType) {
      case 'OrderPlaced':
        order = { id: event.orderId, status: 'placed', items: [], ...event.eventData };
        break;
      case 'ItemAdded':
        order.items = [...(order.items ?? []), event.eventData.item as LineItem];
        break;
      case 'OrderCancelled':
        order.status = 'cancelled';
        break;
      case 'OrderShipped':
        order.status = 'shipped';
        order.shippedAt = event.occurredAt;
        break;
    }
  }

  return order as Order;
}

// Loading an order replays all its events from the beginning
async function loadOrder(orderId: string): Promise<Order> {
  const events = await eventStore.getEventsForAggregate(orderId);
  // events are sorted chronologically - the replay gives current state
  return reconstitute(events);
}

// THE GENUINE BENEFIT: complete, queryable audit history for free
// - When was this order cancelled? Filter for OrderCancelled events
// - What were the original items? Filter for OrderPlaced events
// - Who modified what and when? Every event has a timestamp and actor

