codingChallenge.solutionExample:
// COMMAND SIDE
interface AdjustStockCommand {
  productId: string;
  delta: number;
  reason: 'sale' | 'restock' | 'adjustment';
}

class InventoryCommandService {
  constructor(private writeDb: Database, private eventBus: EventBus) {}

  async adjustStock(command: AdjustStockCommand): Promise<void> {
    const item = await this.writeDb.query(
      'SELECT qty, product_name FROM inventory WHERE id = $1',
      [command.productId]
    );
    if (!item.rows[0]) throw new Error('Product not found');

    const newQty = item.rows[0].qty + command.delta;
    if (newQty < 0) throw new Error(`Insufficient stock: would go to ${newQty}`);

    await this.writeDb.query(
      'UPDATE inventory SET qty = $2 WHERE id = $1',
      [command.productId, newQty]
    );

    // Publish event to trigger read model update
    await this.eventBus.publish('inventory.stock-adjusted', {
      productId: command.productId,
      newQuantity: newQty,
      reason: command.reason
    });
  }
}

// QUERY SIDE: pre-formatted for specific UI needs
interface WarehouseItemView {
  productId: string;
  productName: string;
  currentStock: number;
  stockStatus: 'critical' | 'low' | 'adequate' | 'overstocked';
  reorderRequired: boolean;
}

class InventoryQueryService {
  constructor(private readDb: ReadonlyDatabase) {}

  async getWarehouseDashboard(): Promise<WarehouseItemView[]> {
    const rows = await this.readDb.query(
      'SELECT * FROM inventory_dashboard_view ORDER BY stock_status'
    );
    return rows.map(row => ({
      productId: row.id,
      productName: row.product_name,
      currentStock: row.qty,
      stockStatus: this.classifyStatus(row.qty, row.reorder_threshold),
      reorderRequired: row.qty <= row.reorder_threshold
    }));
  }

  private classifyStatus(qty: number, threshold: number): WarehouseItemView['stockStatus'] {
    if (qty <= 0) return 'critical';
    if (qty <= threshold) return 'low';
    if (qty > threshold * 3) return 'overstocked';
    return 'adequate';
  }
}

sections.content:
The critical differences that determine which style is appropriate
for a specific API use case:

// REST: resource-based, HTTP methods, JSON, stateless
// WHEN: public APIs, simple CRUD, diverse clients, cacheable resources
GET  /orders/:id          -> Order object
POST /orders              -> creates Order
PUT  /orders/:id/cancel   -> cancels Order
// Strength: universally understood, excellent caching (CDNs),
// great tooling, easy to consume from any client
// Weakness: over-fetching (GET /users/123 returns all fields
//   even if client only needs 'name'), multiple round trips for
//   related data

// GRAPHQL: query language, single endpoint, client-specified shape
// WHEN: complex frontends with varying data needs, mobile (bandwidth-
//   sensitive), multiple clients with different field requirements
POST /graphql
body: query {
  order(id: $id) {
    orderId status          // client requests ONLY these fields
    customer { name email } // joins handled by the resolver layer
    items { productName qty } // not the full product object
  }
}
// Strength: no over-fetching, single round trip for complex data,
//   client controls shape
// Weakness: caching complexity, N+1 problem at resolvers (lesson 3's
//   DataLoader exactly addresses this), learning curve

// GRPC: binary protocol (Protocol Buffers), strongly typed,
//   bidirectional streaming possible
// WHEN: internal service-to-service, high throughput, type safety
//   critical, streaming (live data feeds)
// proto definition (shared between services):
service OrderService {
  rpc GetOrder (GetOrderRequest) returns (Order);
  rpc WatchOrderStatus (WatchRequest) returns (stream StatusUpdate);
}
// Strength: ~10x more efficient than REST/JSON, strongly typed by
//   default, native streaming support
// Weakness: not human-readable, requires Proto schema coordination,
//   harder to debug than HTTP/JSON

