import DataLoader from 'dataloader';

// WITHOUT DataLoader: N+1 queries
const resolversWithNPlusOne = {
  Query: {
    orders: async () => db.query('SELECT * FROM orders LIMIT 10') // 1 query
  },
  Order: {
    customer: async (order) =>
      // Called once per order -> 10 queries for 10 orders!
      db.query('SELECT * FROM customers WHERE id = $1', [order.customerId])
  }
};

// WITH DataLoader: 2 queries total regardless of order count
const customerLoader = new DataLoader(async (customerIds: string[]) => {
  // Batch: called ONCE with ALL pending customer IDs
  const customers = await db.query(
    'SELECT * FROM customers WHERE id = ANY($1)',
    [customerIds]
  );
  // DataLoader requires results in the same order as the input IDs
  const customerMap = new Map(customers.rows.map(c => [c.id, c]));
  return customerIds.map(id => customerMap.get(id) ?? null);
});

const resolversWithDataLoader = {
  Query: {
    orders: async () => db.query('SELECT * FROM orders LIMIT 10') // 1 query
  },
  Order: {
    customer: async (order) =>
      // DataLoader batches all pending customer lookups into 1 query
      customerLoader.load(order.customerId) // 1 batch query total
  }
};
// Total: 2 queries (orders + batched customers) vs 11 without DataLoader

