// SCENARIO A: A public API for third-party developers to integrate
// with an e-commerce platform. Clients are diverse (PHP, Python, Ruby,
// mobile, browser). Needs to be cacheable by CDN. Simple CRUD for
// products, orders, customers.

// SCENARIO B: A mobile app (iOS/Android) showing a social feed
// where each post shows: author name + avatar, post text, like count,
// first 3 comments with commenter names. Different UI screens need
// completely different subsets of post data.

// SCENARIO C: Two internal microservices communicating 50,000 times/
// per minute. One service emits real-time price updates; the other
// consumes them. Type safety between the two services is critical.
// Both services are owned by the same team.

// TODO: choose API style for each scenario with reasoning
// TODO: implement a minimal GraphQL schema + DataLoader for Scenario B

codingChallenge.solutionExample:
// SCENARIO A: REST
// Reasoning: public API with diverse third-party clients benefits
// from REST's universal tooling and understanding. CDN caching of
// GET /products works directly. Simple CRUD maps naturally to
// REST's resource model. No complex client-specific data shaping needed.

// SCENARIO B: GraphQL
// Reasoning: multiple screens needing completely different data
// subsets is the canonical GraphQL use case. Mobile bandwidth
// sensitivity makes over-fetching genuinely costly. Multiple
// screens (feed, post detail, profile) can each request exactly
// what they need.

// Minimal GraphQL schema for Scenario B:
const typeDefs = `
  type Query {
    feed(userId: ID!, limit: Int = 20): [Post!]!
  }
  type Post {
    postId: ID!
    text: String!
    likeCount: Int!
    author: Author!
    topComments(limit: Int = 3): [Comment!]!
  }
  type Author {
    userId: ID!
    name: String!
    avatarUrl: String!
  }
  type Comment {
    text: String!
    author: Author!
  }
`;

// DataLoader prevents N+1 on author lookups
const authorLoader = new DataLoader(async (userIds: string[]) => {
  const authors = await db.query(
    'SELECT id, name, avatar_url FROM users WHERE id = ANY($1)',
    [userIds]
  );
  const map = new Map(authors.rows.map(a => [a.id, a]));
  return userIds.map(id => map.get(id) ?? null);
});

const resolvers = {
  Query: {
    feed: (_, { userId, limit }) =>
      db.query('SELECT * FROM posts WHERE ... ORDER BY created_at DESC LIMIT $1', [limit])
  },
  Post: {
    author: (post) => authorLoader.load(post.authorId), // batched
    topComments: (post, { limit }) =>
      db.query('SELECT * FROM comments WHERE post_id = $1 LIMIT $2', [post.id, limit])
  },
  Comment: {
    author: (comment) => authorLoader.load(comment.authorId) // same loader
  }
};

// SCENARIO C: gRPC
// Reasoning: 50k/min internal communication - gRPC's binary protocol
// handles this ~10x more efficiently than REST/JSON. Real-time price
// streaming is a native gRPC use case (server streaming). Both services
// are owned by the same team, making Proto schema coordination practical.
// proto definition:
// service PriceService {
//   rpc StreamPrices (StreamPricesRequest) returns (stream PriceUpdate);
// }

